arguments.command:
curl -s "https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=2018-06-01T00:00:00-07:00&timeMax=2018-06-30T00:00:00-07:00&singleEvents=true&maxResults=250" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for e in d.get('items',[]):
    print('---')
    print(e['id'], '|', e.get('summary'), '|', e.get('status'), '|', e['start'].get('dateTime'))
    desc = e.get('description')
    if desc: print('DESC:', desc[:500])
    conf = e.get('hangoutLink') or (e.get('conferenceData') or {}).get('entryPoints')
    if conf: print('CONF:', conf)
    loc = e.get('location')
    if loc: print('LOC:', loc)
"

